import{_ as t}from"./chunks/9d1b29e721acf84696d2.BkzlOkOn.js";import{_ as o,C as a,o as n,c as l,j as e,a as s,E as i,a5 as h}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"你大脑里困着价值十万美元的知识","description":"","frontmatter":{"title":"你大脑里困着价值十万美元的知识","originalTitle":"You Have $100,000 Of Knowledge Trapped In Your Brain","date":"2022-11-19","originalUrl":"https://thedankoe.com/letters/you-have-100000-of-knowledge-trapped-in-your-brain/","minutes":18,"sourceHash":"95bc09b2f6712442250ee19a558c6c5bc207c17d2eb2bed7e6490ebb5d499be1","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/you-have-100000-of-knowledge-trapped-in-your-brain/"}]]},"headers":[],"relativePath":"letters/you-have-100000-of-knowledge-trapped-in-your-brain.md","filePath":"letters/you-have-100000-of-knowledge-trapped-in-your-brain.md"}'),g={name:"letters/you-have-100000-of-knowledge-trapped-in-your-brain.md"};function m(d,p,c,u,f,b){const r=a("ArticleMeta");return n(),l("div",null,[p[0]||(p[0]=e("h1",{id:"你大脑里困着价值十万美元的知识",tabindex:"-1"},[s("你大脑里困着价值十万美元的知识 "),e("a",{class:"header-anchor",href:"#你大脑里困着价值十万美元的知识","aria-label":'Permalink to "你大脑里困着价值十万美元的知识"'},"​")],-1)),i(r),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/lLl9GkOScFc?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>注意力<em>并不是</em>什么新货币。</p><p>信息才是。</p><p>信息是我们用注意力处理的东西。</p><p>这就是人类真正在做的一切……</p><p>我们处理、存储和使用信息来进行创造或毁灭。</p><p>我愿意相信，像社交媒体这类现代技术背后，存在一种潜意识的、符合进化规律的意图，那就是让我们人类能够获取平常无法获取的信息。从而提高我们生命的潜能。</p><p>信息能让人察觉到机会。</p><p>察觉到机会能带来盈利的想法。</p><p>盈利的想法能带来积极的行为改变。</p><p>操纵信息则会导致死亡、毁灭，以及让你困在自己的脑子里……<a href="https://thedankoe.com/how-cheap-dopamine-prevents-you-from-becoming-high-value/" target="_blank" rel="noreferrer">但我们之前已经谈过这个了</a>。</p><p>相反，我想讨论一下我们所处的信息时代积极的一面（以及你该如何利用它）。</p><p><em>我想让你明白一件事：</em></p><p>万物皆信息。</p><p>我们的基因代码是信息。光是我们眼睛以符合我们生存需求的方式来解读的信息。我们的心智编程是信息随着时间推移不断重复的结果。</p><p>信息是人类形成信念的途径，而信念塑造了我们的思想，并进一步影响我们的行为。</p><p>信息最终会汇聚成张力——或者说阻力——当这种张力被释放时，就会带来发现、创新和创造性的突破。那些能够影响宇宙未来的新想法就此诞生。</p><p>信息是我们得以生存和繁衍的基础，因为它先于任何以信息为根基的事物存在。</p><p><strong>每个人都在努力实现同一个大目标：</strong></p><p><em>尽可能地提高他们的人类体验质量。</em></p><p>我们的思想、情感和行动——全都是信息的表现形式——决定了我们的体验，而体验本身也是以反馈形式存在的信息。</p><p>你看，人类大脑需要有序的信息来保持自身的……好吧，有序。比如体育运动、宗教教义，或是日常惯例。一旦我们通过学习获得了打好一场游戏所需的信息，然后再去玩这款游戏并获得体验，这种体验的质量将远高于我们仅仅被灌输零散信息所获得的体验。</p><p>有<strong>内容</strong>，也有<strong>意识</strong>。</p><p><em>内容</em>的结构决定了幸福感和充实感。这些内容可以代表秩序，也可以代表混乱，后者会导致糟糕的体验质量。</p><p>当大多数人把信息当作逃避生活问题的手段时（通过争论、主流新闻和当天的抓马八卦），另一些人则意识到这是一个陷阱，并让好奇心引导他们走向相反的方向。</p><p>还有一些人，我真的为他们感到难过……那些沉陷于消费负面内容的人，这些内容大肆宣扬售卖课程和其他信息产品有多么糟糕。如果这就是你，请换个视角。你生活在<em>信息时代</em>。<strong>不要因为你在一个卑劣的营销客那里有过一次糟糕的体验，就全盘否定存在的一个整个时代。</strong></p><p>如果你属于充满好奇心的那类人，这封信就是写给你的。为什么？</p><p>因为你脑子里装有价值超过10万美元的信息。</p><p>在这封信中，我想提出一个系统，用于将这些知识打包，并以有价值的方式分发给他人。</p><p>一种利用信息向善的方法，同时开启获取丰厚利润的潜力。</p><p>控制你意识的内容（信息），并（通过内容）引导他人意识的内容。这两者（理想情况下）都会带来高质量的体验。</p><p>一段<em>同时</em>包含自我实现和自我变现的旅程，最终通向自我超越。</p><p>提高你的生活质量，然后是他人。</p><p>注意这些信息（你现在正在阅读的内容）是如何带来潜在机会的。先别急着用你的大脑去扭曲我所说的话。保持开放的心态。在接下来阅读这封信的时间里，让这个想法停留在可能性的范畴中。</p><h3 id="作为一名价值创作者-我是如何将知识转化为七位数收入的业务的" tabindex="-1">作为一名价值创作者，我是如何将知识转化为七位数收入的业务的 <a class="header-anchor" href="#作为一名价值创作者-我是如何将知识转化为七位数收入的业务的" aria-label="Permalink to &quot;作为一名价值创作者，我是如何将知识转化为七位数收入的业务的&quot;">​</a></h3><p>距离我上次讨论自己的故事已经有一段时间了，自那以后我们又迎来了一批新的读者，所以这里只提供一个速览版（我会在某个时候专门写一封信来重写我的故事）：</p><ul><li>我尝试了大多数畅销的技能和在线商业模式，但都失败了</li><li>为了让它们奏效，我损失了8000美元，为了生存，我不得不去找一份网页设计的工作</li><li>我的知识和技能不断复利，直到我终于能够靠网页设计自由职业谋生</li><li>我开始在Twitter上写作，并针对我吸引来的受众调整了我的自由职业报价</li></ul><p>3年前，我开始玩Twitter。</p><p>第一年，我推出了3款信息产品，并赚取了我人生中第一个六位数的信息产品销售额。</p><p>第一个是关于“如何利用网页设计做自由职业”的产品。</p><p>第二个产品教别人我是如何建立这些网站的。</p><p>第三个产品是关于我如何在Twitter上实现增长，并以此作为我获取自由职业客户的唯一途径。</p><p>最终，我把这些产品全都打包打折出售（现在它们是加入Modern Mastery社群的福利）。</p><p>第二年，我开始将触角延伸到Instagram和播客等新平台。</p><p>在这段时间里，由于我自己的原因和缺乏推广，我尝试推出的另外3款产品惨遭失败。一本实体手账、一本自助电子书，以及一门关于设计报价方案（offer creation）的课程（现在同样全是Modern Mastery的福利）。</p><p>我还尝试过销售多个高客单价的产品。我在为创作者提供营销咨询和代笔服务方面取得了成功，但我很快就退出了代笔业务，因为它极度消耗时间（这意味着它违背了我的价值观，与我追求最大时间自由的目标不符）。</p><p>就在那时，我推出了Modern Mastery。</p><p>我利用我已经发布的信息推出并建立这个社群。</p><p>现在，终于到了第三年，我觉得我已经拥有了一套产品和服务矩阵，足以支撑我稳稳度过利润极其丰厚的十年。</p><p>这里的教训是什么（在我们深入探讨你该如何复制这一切之前）？</p><p><strong>1) 我有经验来谈论这些。信息产品、辅导、咨询、自由职业以及代理机构业务，我在这些领域</strong> <em><strong>每一项</strong></em> <strong>的销售额都达到了六位数****。</strong></p><p><em><strong>2) 持续的构建与迭代。</strong></em></p><p>我所做的一切尝试都没有白费。它们为我奠定了基础，让我可以在此之上继续建设，并进一步完善我的想法。</p><p>这正是大多数创作者犯错的地方。</p><p>因为根深蒂固的恐惧，他们迟迟不肯推出自己的东西。</p><p>他们知道第一个产品肯定会很烂，因为这是不可避免的，所以他们阻碍了自己尽早迭代的步伐——而尽早迭代本可以让他们更快地突破收入天花板。</p><p>去构建。</p><p>就现在。</p><h2 id="如何提取困在你大脑中的价值" tabindex="-1">如何提取困在你大脑中的价值 <a class="header-anchor" href="#如何提取困在你大脑中的价值" aria-label="Permalink to &quot;如何提取困在你大脑中的价值&quot;">​</a></h2><blockquote><p>品牌就是你在做什么。\\</p><p>产品就是你如何去做。\\</p><p>营销就是你为什么要这么做。\\</p><p>去做一些能提高你生活质量的事情，教别人你是怎么做到的，并向他们展示为什么他们需要关注。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1592462921468108800?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">November 15, 2022</a></p></blockquote><p>在之前的信件中，我们概述了<a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">将自己产品化</a>以及成为一名<a href="https://thedankoe.com/the-rise-of-the-value-creator-a-new-career-path/" target="_blank" rel="noreferrer">价值创作者</a>的内容。请把这封信当成一人企业系列文章的第三部分（未来还有更多内容）。</p><p>在这封信中，我想讨论一下，在做你一生所热爱之事的的同时，如何构思出完美的产品。</p><p>如果你的个人品牌是围绕着你“在做什么”而建立的，那么你的产品就应该围绕着你“做这件事的独特方式”而建立。</p><p><strong>你在做什么</strong> = 你为了追求更美好生活这个目标，每天日常正在做的事情。</p><p><strong>你如何去做</strong> = 你为了获得更好结果而创造的系统、方法或流程。这源于你的经验和实验。</p><p>我销售过一款关于自由职业的产品，因为我已经通过自由职业赚到了六位数。我知道如何把这件事做好，并且已经建立了一套获取客户、交付服务并使其可持续发展的流程。</p><p>我基于我每天的日常工作建立了一个会员社群。比如提供提醒和问责机制，以确保在专注工作期间完成你每天的“优先任务”。</p><p>我现在销售一款关于写作的产品，因为我是靠着每天2小时写作（兼散步）的习惯，建立了我整个50万以上的受众群。</p><p>其他人销售的是完全违背传统公认“好”建议的极简举重训练计划。如果一个人因为长时间工作，每周只有2小时的训练时间，但他们依然取得了进步……这就是独特性，而且你的营销卖点已经现成地摆在那里了。他们向那些时间有限的人推销一套系统，因为他们已经通过实验做到了拿到结果的地步。</p><p>总结一下，每一个成功将自己产品化的人都做了这3件事：</p><ol><li>他们通过个人和职业发展提高了生活质量</li><li>他们在此过程中学习了必要的技能并培养了兴趣，以提升生活质量</li><li>他们开始在网上发帖，不管他们认为自己的信息有“多基础”</li></ol><p><em>我想问你这样一个问题：</em></p><p>你能想出比这更好的商业模式吗？</p><p>既能实现自我实现、自我变现，又能利用商业作为实现自我超越的方式？</p><p>既能提高你的人类体验质量（这也是每个人都在努力做的事），又能将你沿途学到的东西传承下去？</p><p>当然还有其他可行的商业模式，但我真心相信，这就是未来的趋势。</p><p>如果我们遵循人的天性生活，这个星球上的每一个人都应该拥有一家属于自己的企业。每一家都独一无二。每一家都完美地实现其使命。</p><p>当然，这永远不可能完全发生，但这恰恰意味着它永远不会饱和（当且仅当人们只取自己应得的那份蛋糕并且适可而止时。要懂得知足）。</p><p>本周你可以思考以下3个问题，来头脑风暴出一个有利可图的产品创意：</p><p><strong>1) 你一天中的高光时刻是什么？</strong></p><p>是写作吗？写日记？冥想？瑜伽？还是去健身房？</p><p>这是最困难的部分，因为它往往就在大多数人的眼皮子底下溜走。</p><p>这些事情对我们来说看起来太“平常”了，以至于我们认为别人不会从我们的视角中受益。</p><p>如果你写日记，你能不能为自己设计一款日记本，以后把它卖出去？</p><p>你能创造出属于你自己的瑜伽流程吗？</p><p>一套写作系统怎么样？</p><p>有什么事情是你极其享受、甚至做起来毫不费力，且对你的生活大有裨益，以至于你想把它教给别人的？</p><p><strong>2) 你在哪些方面做得比同龄人更好？</strong></p><p>如果你的朋友对你所做的事情表现出真正的兴趣，有什么事情是你可以倾囊相授的？</p><p>另一个衡量标准是：</p><p>有什么事情是你的朋友因为不理解而批评你的？</p><p>就像奥林匹亚先生冠军和参赛者克里斯·巴姆斯特德（Chris Bumstead）所说的那样，为了成就伟大，他不得不放弃“正常”的生活。他会跳过派对和下馆子，去恢复身体、烹制健康膳食。他的朋友们不理解，但他非常清楚，这会通向他们无法想象的境界。</p><p><strong>3) 你关注谁，他们卖什么？</strong></p><p>成功是反直觉的，这是我能给出的关于构思优秀产品的最佳建议：</p><p>卖那些已经卖得好的东西。</p><p>看在老天爷的份上，请千万不要轻视这个建议。这短短几个字一手奠定了我业务的基础。</p><p>这要求你将自己沉浸在你想要加入的数字环境中，就像通过渗透作用获得成功（或者说“你的人脉就是你的净资产”）。</p><p>密切关注那些你渴望成为的人。</p><p>逆向工程他们的个人资料、内容、落地页、产品以及任何其他东西，这样你就能拼凑出他们成功的拼图（然后复制它）。</p><p><strong>4) 给还没开始的人的额外福利</strong></p><p>如果你还没开始，你需要果断。</p><p>选一条让你稍微感兴趣的路，今天就开始行动。</p><p>看看你书架上的书，浏览器历史记录里你为了<em>学习（而不是为了消遣）</em>而看的视频，以及你在社交媒体上关注的那些激励你变得更好的人。</p><p>设定一个目标，向那些已经实现目标的人学习，并复制他们的成功。</p><h2 id="打造一个盈利产品-用我能解释的最简单方式" tabindex="-1">打造一个盈利产品（用我能解释的最简单方式） <a class="header-anchor" href="#打造一个盈利产品-用我能解释的最简单方式" aria-label="Permalink to &quot;打造一个盈利产品（用我能解释的最简单方式）&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>开始之前，我想重申这封信的整体背景。</p><p>我们是从通过信息将自己产品化的角度来讨论这个问题的。我们不会讨论实体产品、自由职业服务，甚至不会讨论 B2B（企业对企业）销售。</p><p>这是 You2You（你对你）的商业模式，或者说如果你想用不那么自私的方式来定义它的话；即创作者对创作者（Creator2Creator）模式。你的品牌、产品、内容，以及你业务的任何其他方面，都来源于整理你脑海中的信息，通过经验使其巩固，变成别人认为有价值的作品。</p><p>你为自己建造，并吸引那些与你所建造的东西产生共鸣的人。</p><p><strong>大多数人错过的一个关键点：</strong></p><p>这必须公开进行。</p><p>你需要<em>数据</em>来知道你的信息是否有价值。</p><p>饥饿的艺术家喜欢创造<em>他们自己</em>认为有价值的东西，当别人不认可他们的想法时，他们会把无法转型、迭代和创造出真正服务于大众利益的东西归咎于除自己以外的任何人。</p><p>让我们深入探讨。</p><p>使用这7个（非线性的）步骤，将你的自我提升之旅转化为自我变现之旅：</p><p><strong>1) 在特定的技能或兴趣上超越常人</strong></p><blockquote><p>动力让你进入这场游戏。<strong>学习是让你继续玩下去的原因</strong>。创造力是你掌舵的方式。心流是你如何将结果提升到超越所有理性标准和合理预期的涡轮增压器。—— 史蒂芬·科特勒（Steven Kotler）</p></blockquote><p>我们以前已经多次讨论过技能和兴趣，所以我假设你们中的许多人已经开始学习自己感兴趣的东西了。</p><p><em>这是大多数人不想听到的事实：</em></p><p>如果你在任何尝试中没有看到你想要的结果，<strong>那是因为你还不够熟练</strong>。你没有投入必要的时间去学习如何参与、如何赢，以及如何在这场游戏中游刃有余。</p><p>如果不专注于学习，我们就容易把注意力集中在我们还没有达到的期望结果上。我们开始拿自己和那些技能水平更高的人（在生手眼里看不出来的差距）所取得的结果进行比较。</p><p>前几天，我的一篇帖子上有一条评论。</p><p>有人问，为什么他在遵循了关于如何增长的常见建议后，在社交媒体上依然没有增长。</p><p><em>这仍然是一个技能问题。</em></p><p>单靠学习，你对一项技能的了解只有那么多。你必须把你的技能浸泡在市场中。这会扩大你对该技能的认知。如果你不盲目地重复别人告诉你的做法，你就能捕捉到微小的细节。</p><p>你可以去评论、与大账号互动，或者遵循现有的任何其他社交媒体增长的基本建议——但如果你没有看到结果，你必须找出是什么导致了这种阻碍。</p><p>是你传达的信息有问题？你的英语流利吗？你会在标点符号前加空格吗 ？是不是你学到的某个关键部分被你认为不重要了？</p><p>在大多数情况下，学习如何写作、如何营销、如何销售是绝对不会错的。</p><p>商业在本质上是交易性的。</p><p>写作、营销和销售会教你人类心理学，但这是一种能溢出到你生活中所有交易领域的实用方式。</p><p><strong>2) 每天用这些技能去建造一些东西</strong></p><p>如果你没什么东西要建造，那就别学了。</p><p>但别被这话误导，从而认为你的整个人生不是你正在建造的东西。</p><p>意思是，要残酷无情地消除分心。源于分心的信息会导致头脑混乱，正如我们所讨论过的，<a href="https://thedankoe.com/the-cure-to-caring-what-people-think/" target="_blank" rel="noreferrer">这会导致不知所措、焦虑和缺乏清晰度</a>——这与建造恰恰相反。</p><p>如果你在学营销，那就建立一个品牌。</p><p>如果你在学灵性，那就建立一种生活。</p><p>如果你正在学习源自这两者的无数技能中的任何一种，把你学到的东西应用到你的生活、业务中，或者两者兼顾。在脑海中牢记这个意图。</p><p><strong>3) 记录你的学习、发现和成果</strong></p><p>记笔记。</p><p>写内容。</p><p>把互联网当成一种记录对你有意义、能激发兴奋感且有价值的信息的方式。记录你井然有序的意识，让别人也能从中受益。</p><p>互联网是一个公开的笔记软件、公开的日记本和公立学校，它是你通往巨大机遇的捷径，但前提是你把它当回事。</p><p>我们上周讨论过<a href="https://thedankoe.com/how-i-remember-everything-i-learn/" target="_blank" rel="noreferrer">“开始、建造、教授”是如何保留所学知识的最佳方式。</a></p><p><strong>4) 为了全面的理解去进行实验</strong></p><p>我一直喜欢“按我自己的方式”做事。</p><p>我自己的方式 = <em>实践来自多个来源的最佳教导，直到我拥有自己独特的做事方式。</em></p><p>在健身方面，我尝试了天底下每一种训练方式。我最喜欢的是每周3天的极简、高强度、全身训练。</p><p>在饮食方面，我尝试过纯素、祖先饮食法、纯肉饮食、IIFYM（按需定算）、生酮，以及间歇性断食等热量限制模式。</p><p>从那次实验中，我可以在健康领域游刃有余。我可以从那些饮食方式中汲取最享受的部分，并创造出一种我真心喜欢（且能让我获得效果）的新模式。</p><p>如果我想给我的饮食或训练计划随便贴个名字然后卖掉，我完全可以做到。而且凭借我的营销知识，我会做得相当出色。但我现在还是先让那个赛道暂时不那么拥挤吧 😉</p><p><em><strong>这就是整合者（synthesizer）之道。</strong></em></p><p>既然大多数细分领域在多个行业中都已经被填满，这就是未来的出路，因为它允许无限的创造力，并且不会饱和。</p><p>就像电子舞曲是如何随着技术进步应运而生的一样。每周都有新的流派和子流派被创造出来。电子音乐行业之所以持续增长，是因为技术让 DJ 和制作人能够进行无限的创新。</p><p>创作者只是 IJ。</p><p>创意瘾君子（Idea Junkies）。</p><p>想法是声音，内容是歌曲。</p><p>创作你的混音，大声播放出来，并吸引一批观众。</p><p><strong>5) 迭代你的流程以获得效率和成果</strong></p><p>一旦你对你想追求的技能或兴趣有了全面的理解，就创建你自己的流程。</p><p>说真的，写下你自己的 SOP。</p><p>SOP = 商业中的标准作业程序（Standard Operating Procedure）。</p><p>就像我做网页设计师时为客户创建网站的 SOP，后来变成了一门网页设计课程（当然，我得在课程里增加一点细节，但这都是简单的部分）。</p><p>它是一组带有描述的步骤，说明如何执行某项任务以获得结果。一个系统。</p><p>当你遵循这个系统并从使用中获得直接经验时，你会遇到问题。特别是在最初的几次。</p><p>当你遇到这个问题时，对你的系统做一点小小的改变。</p><p>再次测试，看看是否有效，然后重复这个过程，直到你拥有一套能稳定获得结果的系统。</p><p>这方面的另一个例子是我的 <a href="https://learn.thedankoe.com/planner" target="_blank" rel="noreferrer">Power Planner</a>。</p><p>我为自己创建了一个生产力系统。</p><p>我每天都会写下某些特定的事情，以确保我正在完成优先级任务。我尝试了多个计划表，并从中汲取了我最喜欢的部分。</p><p>最终，我把它打包，把设计图发给了打印店，做成了一个实体的计划本（后来我停止售卖了，因为我讨厌在我狭小的公寓里处理库存）。</p><p>我的课程 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">The 2 Hour Writer</a>，一开始是我根据我学到的关于写作、说服力、社交媒体增长和营销的知识，为撰写新闻通讯而创建的模板。</p><p>那个花了更多一点的测试和经验，但这个道理依然成立。</p><p>我在 <a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">MMHQ</a> 内部展示了我在 Notion 中创建系统并将其变成产品的过程。</p><p><strong>6) 偷走已经奏效的营销和结构</strong></p><p>“卖那些已经卖得好的东西。”</p><p>这是我收到过的最好的一条反直觉的建议。</p><p>我创建了 The 2 Hour Writer，因为我知道在我的推特（Twitter）小圈子里，写作市场有多火爆。</p><p>我知道有人光是在 Twitter 上卖写作类产品，一年就能卖出7位数以上的销售额。</p><p>我知道我对写作有独到的见解，即便我不认为自己是个作家，而且我有结果来证明这一点。</p><p>为了让我自己更轻松，我直接借鉴了某些作者落地页上最精华的部分。</p><ul><li>标题</li><li>痛点问题</li><li>报价和课程结构</li><li>保证、好处、常见问题解答以及其他</li><li>定位（不是“靠写作在网上赚钱”）</li></ul><p>这跟我创造过的任何其他产品没什么不同。</p><p>我的第一个产品是一本关于网页开发者如何开始自由职业的电子书，它的诞生是因为：</p><ol><li>我知道开发者市场很火，他们喜欢买课程（我自己就曾是一名开发者）</li><li>他们都在 Twitter 上，并且积极关注别人</li><li>Udemy（一个课程平台）上大多数开发课程的定价都太低了。我知道我必须通过社交媒体上的个人品牌来形成差异化，以此来提高收费并获得可持续的收入。</li><li>我自己也买过一个类似的自由职业课程，并从中获得了结果</li></ol><p>既然我拿到了结果，也有自己做事的门道，我就决定创造一个属于我自己的。</p><p>我可以把那位卖家的内容、营销以及电子书本身，当成我自己产品的灵感。</p><p>我为我的产品列出大纲，从别人那里汲取灵感以确保我涵盖了所有内容，然后用我脑子里的知识把它写了出来。</p><p>买过的人还会再买。记住这一点。</p><p>同一个主题的课程，你买过多少个？那你凭什么认为，如果你做了一个类似的东西，别人就不会买你的呢？</p><p>我个人不会为很多产品做联盟推广，因为我通常自己就有成果，也不想要不到一半的收益。</p><p>如果我想要什么东西，我就自己创造它。如果我想卖某种特定类型的产品，我就自己创造它。</p><p><strong>7）建立分发渠道并系统化推广</strong></p><p>做生意有很多环节在同时运转。</p><p>品牌是那种你不需要太多改动的东西。</p><p>产品也类似，但你应该在合适的时机维护和更新它。</p><p>而内容和营销，这两者则需要持续投入努力。</p><p>内容是用来建立分发渠道的。</p><ul><li>一群受众</li><li>一份邮件列表</li><li>如果你愿意，还可以有一个社群</li></ul><p>营销是用来通过推广来分发你的产品的。</p><ul><li>在社交媒体帖子中植入产品</li><li>在你的通讯中推广</li><li>变换角度和措辞</li></ul><p>你在这场伟大的线上游戏中取得成功的唯一方式，就是<strong>坚持与迭代</strong>。</p><p>制造大量噪音，然后专注捕捉信号。</p><p>用一个月的时间，把一堆推文扔到墙上试试看。</p><p>（务必确保你在通过社交、回复或付费增长等方式，努力让更多人看到你的内容）。</p><p>留意哪些内容表现<strong>最好</strong>，然后开始用1000种不同的方式讲同一件事。把它发到其他平台，把它变成一期通讯的主题，再把那期通讯变成一个YouTube视频。</p><p>营销也是同样的道理。</p><p>推广，看哪个带来最多点击和转化，加倍投入，持续测试，然后重复这个过程。</p><p>记住，是十年心态，不是两周心态。</p><p>经过1到3年后，你的内容和推广会好到让那些“怎么做”的建议对你毫无意义。</p><p>你学会驾驭自我觉察和直觉的力量。</p><p><strong>但有个前提：</strong></p><p>你必须开始写作、构建和推广。</p><p>如果你感到焦虑，记住，未知会随着时间变成已知。</p><p>你终究要迈出这一步，不如就从现在开始。</p><p>一个自主、盈利且充满成就感的未来正在等待你。</p><p>——丹·库伊（Dan Koe）</p><h3 id="本周动态" tabindex="-1">本周动态 <a class="header-anchor" href="#本周动态" aria-label="Permalink to &quot;本周动态&quot;">​</a></h3><p>数字经济学（Digital Economics）的报名将持续到明晚。如果你一个月前错过了报名，想要中途加入，现在就是时机。下一期将在二月开课。</p><p><a href="https://upgrade.digitaleconomics.school/" target="_blank" rel="noreferrer">点此报名。</a></p><p>在现代精通（Modern Mastery）中，我发布了一套规划三年独特内容的策略。就像是构建一套心理战策略，让你在别人专注于模仿大师时，成为真正的大师。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可花5美元加入。</a></p><p>一个关于如何逃离矩阵的新YouTube视频明天上线。上周的视频是关于如何“做自己”的哲学思考。</p><p><a href="https://youtube.com/c/DanKoeTalks" target="_blank" rel="noreferrer">点此观看两个视频。</a></p><hr><p><a href="/en/letters/you-have-100000-of-knowledge-trapped-in-your-brain">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',226))])}const y=o(g,[["render",m]]);export{w as __pageData,y as default};
